content:
Here is a complete, idiomatic Terraform implementation that refactors duplicated environment blocks into a single `for_each`-driven module. It includes environment variable files, zero-diff state migration commands, and explicit mapping to your acceptance criteria.

### 📁 Project Structure
```
terraform/
├── variables.tf
├── main.tf
├── dev.tfvars
├── prod.tfvars
└── migrate_state.sh
```

---

### 1. `terraform/variables.tf`
```hcl
variable "environments" {
  description = "Map of environment configurations for for_each iteration"
  type = map(object({
    region               = string
    vpc_id               = string
    subnet_ids           = list(string)
    eks_instance_type    = string
    eks_node_count       = number
    rds_class            = string
    rds_multi_az         = bool
    rds_encrypted        = bool
    s3_replicate         = bool
    s3_replicate_region  = string
    iam_mode             = string # "user" or "oidc-role"
    oidc_issuer_url      = string
    acm_cert_arn         = string
    use_cloudfront       = bool
    db_secret            = string # Passed encrypted via SOPS or CI/CD
  }))
  default = {}
}

variable "account_id" {
  description = "AWS Account ID for unique resource naming"
  type        = string
}
```

---

### 2. `terraform/main.tf`
```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.environments["dev"].region # Use dev region for base provider; cross-region resources handled inline
}

# ─────────────────────────────────────────────────────────────────────────────
# EKS CLUSTER & NODE GROUPS
# ─────────────────────────────────────────────────────────────────────────────
resource "aws_eks_cluster" "app" {
  for_each = var.environments
  name     = "app-${each.key}"
  version  = "1.28"

  role_arn = aws_iam_role.eks[each.key].arn

  vpc_config {
    subnet_ids = each.value.subnet_ids
  }
}

resource "aws_eks_node_group" "app" {
  for_each = var.environments
  cluster_name    = aws_eks_cluster.app[each.key].name
  node_group_name = "app-${each.key}-nodes"
  node_role_arn   = aws_iam_role.node[each.key].arn
  subnet_ids      = each.value.subnet_ids

  scaling_config {
    desired_size = each.value.eks_node_count
    max_size     = each.value.eks_node_count
    min_size     = 1
  }

  instance_types = [each.value.eks_instance_type]

  depends_on = [
    aws_iam_role_policy_attachment.eks-cluster,
    aws_iam_role_policy_attachment.eks-node
  ]
}

# ─────────────────────────────────────────────────────────────────────────────
# S3 BUCKET (Assets)
# ─────────────────────────────────────────────────────────────────────────────
resource "aws_s3_bucket" "assets" {
  for_each = var.environments
  bucket   = "app-assets-${each.key}-${var.account_id}"
  tags     = { Environment = each.key }
}

resource "aws_s3_bucket_versioning" "assets" {
  for_each = var.environments
  bucket   = aws_s3_bucket.assets[each.key].id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  for_each = var.environments
  bucket   = aws_s3_bucket.assets[each.key].id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  for_each = var.environments
  bucket   = aws_s3_bucket.assets[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Conditional cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "assets" {
  for_each = { for k, v in var.environments : k => v if v.s3_replicate }
  bucket   = aws_s3_bucket.assets[each.key].id
  role     = aws_iam_role.s3-replication[each.key].arn

  rule {
    id     = "replicate-${each.key}"
    status = "Enabled"
    destination {
      bucket = "arn:aws:s3:::app-assets-replica-${each.key}-${var.account_id}"
      region = each.value.s3_replicate_region
    }
  }
}

# ─────────────────────────────────────────────────────────────────────────────
# RDS POSTGRESQL
# ─────────────────────────────────────────────────────────────────────────────
resource "aws_db_subnet_group" "app" {
  for_each = var.environments
  name     = "app-db-${each.key}"
  subnet_ids = each.value.subnet_ids
}

resource "aws_security_group" "rds" {
  for_each = var.environments
  name        = "app-rds-${each.key}"
  description = "Allow PostgreSQL traffic"
  vpc_id      = each.value.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"] # Restrict to VPC CIDR
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "app" {
  for_each = var.environments
  identifier = "app-db-${each.key}"
  engine     = "postgres"
  version    = "15.4"

  instance_class          = each.value.rds_class
  allocated_storage       = 20
  storage_encrypted       = each.value.rds_encrypted
  multi_az                = each.value.rds_multi_az
  deletion_protection     = true
  backup_retention_period = 7
  publicly_accessible     = false

  db_subnet_group_name = aws_db_subnet_group.app[each.key].name
  vpc_security_group_ids = [aws_security_group.rds[each.key].id]

  # Password managed via AWS Secrets Manager integration (best practice)
  manage_master_user_password = true
  master_user_secret_kms_key_id = "alias/aws/secretsmanager" # or custom KMS
}

# ─────────────────────────────────────────────────────────────────────────────
# IAM (User for Dev, OIDC Role for Prod)
# ─────────────────────────────────────────────────────────────────────────────
locals {
  iam_users = { for k, v in var.environments : k => v if v.iam_mode == "user" }
  iam_roles = { for k, v in var.environments : k => v if v.iam_mode == "oidc-role" }
}

resource "aws_iam_user" "app" {
  for_each = local.iam_users
  name     = "app-svc-${each.key}"
  tags     = { Environment = each.key }
}

resource "aws_iam_access_key" "app" {
  for_each = local.iam_users
  user     = aws_iam_user.app[each.key].name
}

resource "aws_iam_role" "app" {
  for_each = local.iam_roles
  name     = "app-svc-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Federated = each.value.oidc_issuer_url }
      Action   = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        "StringEquals" = { "token.actions.githubusercontent.com:aud" = "sts.amazonaws.com" }
      }
    }]
  })
}

# Least-privilege policy (applies to both user & role via attachment)
resource "aws_iam_policy" "app_least_privilege" {
  for_each = var.environments
  name     = "app-policy-${each.key}"
  policy   = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:PutObject",
        "rds-db:connect",
        "secretsmanager:GetSecretValue"
      ]
      Resource = [
        aws_s3_bucket.assets[each.key].arn,
        "${aws_s3_bucket.assets[each.key].arn}/*",
        aws_db_instance.app[each.key].arn,
        aws_secretsmanager_secret.db[each.key].arn
      ]
    }]
  })
}

# ─────────────────────────────────────────────────────────────────────────────
# HTTPS EXPOSURE (ALB + Optional CloudFront)
# ─────────────────────────────────────────────────────────────────────────────
resource "aws_lb" "app" {
  for_each = var.environments
  name               = "app-alb-${each.key}"
  internal           = true # Internal for both; CloudFront terminates HTTPS for prod
  load_balancer_type = "application"
  subnets            = each.value.subnet_ids
}

resource "aws_lb_target_group" "app" {
  for_each = var.environments
  name     = "app-tg-${each.key}"
  port     = 80
  protocol = "HTTP"
  vpc_id   = each.value.vpc_id
}

resource "aws_lb_listener" "https" {
  for_each = var.environments
  load_balancer_arn = aws_lb.app[each.key].arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2021-06"
  certificate_arn   = each.value.acm_cert_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app[each.key].arn
  }
  # Note: No 80->443 redirect rule added per acceptance criteria
}

# ─────────────────────────────────────────────────────────────────────────────
# SECRETS (DB Connection String)
# ─────────────────────────────────────────────────────────────────────────────
resource "aws_secretsmanager_secret" "db" {
  for_each = var.environments
  name     = "/app/${each.key}/db-connection-string"
}

resource "aws_secretsmanager_secret_version" "db" {
  for_each = var.environments
  secret_id     = aws_secretsmanager_secret.db[each.key].id
  secret_string = each.value.db_secret
}
```

---

### 3. `terraform/dev.tfvars` & `terraform/prod.tfvars`
```hcl
# dev.tfvars
environments = {
  dev = {
    region              = "us-east-1"
    vpc_id              = "vpc-0dev123"
    subnet_ids          = ["subnet-0dev1", "subnet-0dev2"]
    eks_instance_type   = "t3.medium"
    eks_node_count      = 2
    rds_class           = "db.t3.micro"
    rds_multi_az        = false
    rds_encrypted       = false
    s3_replicate        = false
    s3_replicate_region = ""
    iam_mode            = "user"
    oidc_issuer_url     = ""
    acm_cert_arn        = "arn:aws:acm:us-east-1:123456789012:certificate/dev-cert"
    use_cloudfront      = false
    db_secret           = "sops://secrets/dev.db.enc" # Decrypted at runtime via SOPS provider or CI
  }
}
account_id = "123456789012"
```

```hcl
# prod.tfvars
environments = {
  prod = {
    region              = "us-east-1"
    vpc_id              = "vpc-0prod456"
    subnet_ids          = ["subnet-0prod1", "subnet-0prod2"]
    eks_instance_type   = "t3.large"
    eks_node_count      = 4
    rds_class           = "db.t3.medium"
    rds_multi_az        = true
    rds_encrypted       = true
    s3_replicate        = true
    s3_replicate_region = "us-west-2"
    iam_mode            = "oidc-role"
    oidc_issuer_url     = "https://oidc.eks.us-east-1.amazonaws.com/id/PRODCLUSTERID"
    acm_cert_arn        = "arn:aws:acm:us-east-1:123456789012:certificate/prod-cert"
    use_cloudfront      = true
